package weekly_Assignments;

public class Employee_Assignment {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		/*
		Employee Details
		Create a Java program to store and print the following employee details:
    	• Employee ID
    	• Age
    	• Salary
    	• Department Initial
    	• Whether the employee is permanent
		Use appropriate primitive data types.
		Expected Output:
		Employee ID: 1001
		Age	: 28
		Salary: 55000.50
		Department: T
		Permanent: true
		 */
		
		int employee_ID = 1001;
		short age = 28;
		double salary = 55000.50;
		char department = 'T';
		boolean permenant = true;
		
		System.out.println("The employee ID is: "+ employee_ID);
		System.out.println("The employee age is: "+ age);
		System.out.println("The employee salary is: "+salary);
		System.out.println("The employee department is: "+ department);
		System.out.println("Is the employee permenant: "+permenant);

	}

}
